ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_any_12"] = {
{"s12_house_coffee_warm_009","any",2,"reg=civilian,worker|tmp=seasoned|mood=fear|world=vehicle",{1,"I got in that farmhouse out Echo Creek Road and there was coffee in the pot",2,"Old coffee",1,"Warm coffee - that's all, that's why I slept in the bed of the truck that night"}},
{"s12_house_upstairs_nailed_010","any",2,"reg=civilian,family|tmp=fresh|hour=21,4|mood=fear|world=building",{1,"Somebody nailed the upstairs shut from the outside, sixteen penny nails, all around the frame",2,"To keep something in",1,"That's what I said, then Delbert asked why they done the hall closet too",2,"Don't tell me the rest",1,"Wasn't going to"}},
{"s12_house_answering_loop_011","any",2,"reg=civilian,worker|tmp=seasoned|hour=22,3|mood=grim",{1,"The answering machine in that house was still on the power and it kept playing the same four seconds",2,"Somebody's message",1,"No voice, just a glass getting set down on wood, over and over",2,"Battery backup thing",1,"I'd like that to be it, I pulled the cord and left anyway"}},
{"s12_house_shoes_by_door_012","any",2,"reg=rescue,civilian|tmp=seasoned|mood=sad|world=door",{1,"Nine pairs of shoes lined up inside that front door - big to little, left to right",2,"A family with nine?",1,"Two bedrooms in that house, I counted the beds twice 'cause I wanted the math to work"}},
{"s12_house_fridge_notes_013","any",3,"reg=civilian,family|tmp=fresh,seasoned|hour=19,2|mood=fear|world=door,building",{1,"Fridge in the Six place had about forty notes on it - magnets, tape, the whole door",2,"Grocery lists?",1,"Same three words on every one of 'em, same handwriting, getting bigger",3,"What'd they say?",1,"I'd rather not put it in my mouth - ask Junior, he read one out loud"}},
{"s12_house_bed_made_014","any",2,"reg=law,rescue|tmp=seasoned|mood=grim|world=building",{1,"Whole house tore to pieces and the one bed upstairs was made up like a hotel",2,"Hospital corners?",1,"Hospital corners, and a glass of water on the nightstand with no dust on it"}},
{"s12_house_swing_inside_015","any",2,"reg=worker,civilian|tmp=seasoned|mood=fear|world=building",{1,"Somebody took the porch swing off the porch and hung it in the living room",2,"Hung it",1,"Chains through the ceiling joists and everything, did a better job than the porch",2,"Why",1,"That is the exact thing I was thinking about when I walked out"}},
{"s12_house_sav_rite_note_016","any",2,"reg=civilian,family|tmp=fresh,seasoned|hour=20,3|mood=fear|world=window",{1,"I left a note taped in the Sav Rite window saying where we'd be - went back Thursday for salt",2,"Somebody took it?",1,"Somebody wrote under it - two words - 'we know'",2,"Get the note",1,"I did not take the note, I ain't touching that note"}},
{"s12_house_mirrors_down_017","any",2,"reg=civilian,worker|tmp=seasoned|hour=21,2|mood=grim|world=building",{1,"Every mirror in the house was took down and set against the wall facing in",2,"That's a church thing, my mamaw done that when her sister passed",1,"Then somebody in that house was grieving real careful - there's nine mirrors in a house?",2,"There is if you count the bathroom cabinets",1,"I counted the cabinets, I got eleven"}},
{"s12_house_dog_bowl_full_018","any",2,"reg=family,civilian|tmp=fresh|mood=fear|world=building",{1,"The dog bowl in the kitchen was full, water, not food",2,"So the dog's around",1,"No dog, no hair on the furniture, no leash, no dog dish smell - one full bowl"}},
{"s12_house_clock_wound_019","any",2,"reg=worker,civilian|tmp=seasoned|hour=19,1|mood=grim",{1,"Mantel clock in that house was wound, right time, too, within a minute",2,"Eight day clock, they run a week",1,"It's been longer than a week since the sixth, Earl",2,"Yeah",1,"So somebody's been in that front room with a key in their hand"}},
{"s12_house_kids_room_swept_020","any",2,"reg=rescue,law|tmp=seasoned|mood=sad|world=window",{1,"Little girl's room in the house on Frogtown was the only room anybody had cleaned",2,"Cleaned",1,"Bed stripped, floor swept, curtains open, the rest of that house you couldn't walk in"}},
{"s12_house_two_doors_locked_021","any",2,"reg=swat,law|tmp=veteran|mood=calm|world=door,building",{1,"Locks on that house were backwards, deadbolt keyed on the inside of the bedroom doors",2,"Somebody was locking people in a bedroom",1,"Or locking themselves in two of 'em at once, which is the part I can't do"}},
{"s12_house_cassette_hiss_022","any",2,"reg=civilian,worker|tmp=seasoned|hour=22,4|mood=fear",{1,"There was a tape in the boombox on the counter - I pushed play, which was stupid",2,"What was on it?",1,"Somebody breathing and a floor fan, forty five minutes a side of that",2,"How do you know how long it went?",1,"'Cause I sat there and listened to the whole thing - don't ask me why, I don't know why"}},
{"s12_house_stairs_worn_023","any",2,"reg=worker|tmp=seasoned|mood=grim|world=stairs,building",{1,"Dust on them cellar stairs was wore off in the middle - a path",2,"Family used the cellar, everybody does in a storm",1,"Dust on the top step was thick as a quilt - the path starts at step two and goes down"}},
{"s12_house_every_light_on_024","any",2,"reg=civilian,family|tmp=fresh,seasoned|hour=21,4|mood=fear|world=door,generator",{1,"House out past Bethel Ridge had every light in it burning - power's been off since the seventh",2,"Generator",1,"Lamps, Glenda - kerosene lamps, somebody filled and lit nine lamps and then left the door open"}},
{"s12_house_smell_of_soap_025","any",2,"reg=rescue,civilian|tmp=seasoned|mood=fear|world=road",{1,"That whole street smells like you'd expect, you get in that one house and it smells like soap",2,"Somebody's washing in there",1,"Something's washing in there, I shouldn't have said it that way - forget how I said it"}},
{"s12_house_hand_prints_low_026","any",3,"reg=law,rescue|tmp=seasoned|mood=grim|world=building",{1,"Hand prints on the hallway wall, both sides, about knee high",2,"Kid crawling",1,"Kid crawling both directions for what looks like a month",3,"There's no kid on the census for that address",1,"I know there ain't, that's why I'm standing here telling you instead of writing it down"}},
{"s12_house_tv_on_static_027","any",2,"reg=civilian,worker|tmp=seasoned|hour=23,5|mood=fear|world=road",{1,"Television in that front room was on, nothing but snow, but it was on and it was warm",2,"Power's out on that road",1,"I know what the power is - you want to go look at it with me? No? Alright then"}},
{"s12_house_pantry_labels_028","any",2,"reg=civilian,family|tmp=seasoned|mood=grim|world=building",{1,"Pantry in the Halbert house was full and every can had a name wrote on the lid in marker",2,"Family split up the food - that's smart",1,"Seven names, I looked in the phone book - that house is two people, been two people for years"}},
{"s12_house_no_photographs_029","any",2,"reg=civilian,worker|tmp=seasoned|mood=grim",{1,"Somebody had took every photograph out of the frames and left the frames hung up",2,"Folks take pictures when they run",1,"They don't rehang the frames, they don't get 'em level, either - those were level"}},
{"s12_house_chalk_nine_030","any",2,"reg=civilian,family|tmp=fresh,seasoned|hour=20,2|mood=fear|world=door,building",{1,"There's chalk numbers on every front door on Halbert Street - ones and twos mostly",2,"Somebody counting the dead inside - Guard does that",1,"One house has a nine on it, nine, in a two bedroom house",2,"Which house",1,"That's the one I ain't going back to, so you'll have to go read the number yourself"}},
{"s12_house_bible_open_031","any",2,"reg=rescue,family|tmp=seasoned|mood=sad|world=building",{1,"Bible on the kitchen table, open, and a spoon laid across the page to hold it",2,"Which page?",1,"Doesn't matter which page, the spoon's clean, is the thing - everything else in there's black"}},
{"s12_house_two_locks_new_032","any",2,"reg=worker,civilian|tmp=seasoned|mood=grim|world=door,building",{1,"New hasp on the outside of that bedroom door, brass, hardware store sticker still on it",2,"Bought after all this started",1,"Bought and hung, somebody drove to the Handy Pantry in July to buy a lock for a bedroom"}},
{"s12_house_cold_room_033","any",2,"reg=civilian,worker|tmp=fresh,seasoned|hour=13,19|mood=fear|world=building",{1,"Ninety six degrees out and the back room of that house was cold - not cool - cold",2,"Basement under it?",1,"Slab, I put my hand flat on the floor like a fool and I still don't know why I done that"}},
{"s12_house_stacked_shoes_034","any",2,"reg=outlaw,crime|tmp=predator,seasoned|mood=grim",{1,"We turned over a place on Tanner and left it - first time I ever left a full house",2,"Somebody home?",1,"Somebody had every shoe in that house in one pile in the bathtub - filled it",2,"And you walked out over shoes",1,"I walked out over the fact that they was all tied together - laces - every one"}},
{"s12_house_kitchen_right_035","any",2,"reg=family,civilian|tmp=seasoned|hour=19,23|mood=sad|world=building",{1,"Kitchen was kept just the way my mother kept hers - dishes done, towel over the handle",2,"That'd be a comfort",1,"It was, for about a minute, then I noticed it wasn't my mother's kitchen and I'd never been in that house"}},
{"s12_house_screen_latched_036","any",2,"reg=law|tmp=seasoned,veteran|mood=calm|world=door",{1,"Back door kicked off the frame, splinters everywhere, screen door in front of it latched shut",2,"Latched from which side?",1,"Inside, so whoever come through that door went back out and latched a screen behind 'em"}},
{"s12_house_refuse_last_bit_037","any",3,"reg=civilian,worker|tmp=seasoned|hour=21,3|mood=fear|world=door,building",{1,"So we get in the Kelso place through the side door, 'cause the back was chained",2,"Chained from outside?",1,"Chained from outside, and there's a chair pulled up to the cellar door with a plate on it",3,"A plate of what?",1,"I ain't telling that part - Earl was stood right there, ask Earl"}},
{"s12_house_bible_on_bible_038","any",2,"reg=rescue|tmp=seasoned|mood=grim",{1,"I've been in a lot of houses this month, Brother - I come out of one on Frogtown and sat in the grass",2,"You want to tell it?",1,"Not real bad, somebody had wrote out the same verse about two hundred times on butcher paper",2,"Which verse?",1,"It quit being a verse about page four, after that it was just the one word over and over"}},
{"s12_house_swear_bible_039","any",2,"reg=civilian,family|tmp=fresh|hour=20,2|mood=fear|world=window",{1,"I'll put my hand on a Bible about this - go get one, I'll do it right now",2,"Nobody's calling you a liar, just tell it",1,"The rocking chair in that front room was going when I come in and it was going when I left",2,"Draft",1,"Windows are painted shut, I checked 'em - all four"}},
{"s12_house_apologize_telling_040","any",2,"reg=civilian,worker,family|tmp=seasoned|hour=23,4|mood=fear|world=building,rooftop",{1,"I shouldn't be dumping this on you, it's late and you got watch at four",2,"Go on",1,"That house on Piney Fork, somebody left a chair on the roof - kitchen chair, dead center of the roof",2,"Alright",1,"That's all - that's it - sorry - go back to sleep"}},
{"s12_house_coda_rule_041","any",2,"reg=family,civilian|tmp=seasoned|mood=grim",{1,"So that's why nobody goes past the second cattle gate on the Kelso place - not for water, not for nothing",2,"You never said what you saw",1,"Nope, and don't you go past the gate"}},
{"s12_house_friend_of_friend_042","any",2,"reg=civilian,worker|tmp=seasoned|hour=19,1|mood=fear",{1,"This ain't mine, so take it how you want, fella that fixed our well told me",2,"Otho? Otho don't talk",1,"That's my point, he said he found a house where somebody'd set the table for him - plate, fork, glass of tea",2,"For him",1,"His initials on a napkin, he didn't finish telling it and I didn't make him"}},
{"s12_house_downgrade_end_043","any",2,"reg=civilian,family|tmp=fresh,seasoned|hour=22,3|mood=fear",{1,"Probably nothing, probably somebody's hog got in the house and knocked stuff around",2,"A hog",1,"A hog - sure, I moved my bedroll out to the shed, but it's probably a hog"}},
{"s12_house_hedge_number_044","any",2,"reg=worker,civilian|tmp=seasoned|mood=grim|world=window,building",{1,"There was four beds made up in that one room - five, I'd say five",2,"In one room?",1,"Five beds, all facing the same wall, and there ain't a window in that wall"}},
{"s12_house_gentleman_word_045","any",3,"reg=civilian,family|tmp=seasoned|hour=21,2|mood=fear|world=fence,building",{1,"We took to calling him the gentleman, made it easier to say out loud at supper",2,"Calling who?",1,"Whoever moves the furniture in that house at the end of Tanner - little bit every week",3,"You been back?",1,"I go to the fence, I look at the porch, I don't go up on the porch"}},
{"s12_house_answer_wrong_q_046","any",2,"reg=civilian,worker|tmp=seasoned|hour=22,4|mood=fear|world=vehicle,window",{1,"Did it see you, is what I'm asking",2,"It was hot that night - real hot, I had the truck window down, is the thing",1,"That ain't an answer",2,"No, it ain't"}},
{"s12_house_military_log_047","any",2,"reg=military,elite|tmp=veteran|mood=calm",{1,"House at grid reference by the water tank, I'm marking it no entry and I'm not explaining it",2,"Say again? That's not a disposition, Sergeant",1,"Then write occupied, somebody in there put our boot prints in a notebook - ours - from Tuesday"}},
{"s12_house_prisoner_take_048","any",2,"reg=prison,outlaw|tmp=predator|mood=grim|world=building",{1,"I done eleven years in a building where a man learns what a hallway sounds like",2,"Congratulations",1,"That house on Halbert sounds like a hallway with somebody waiting at the end of it - I ain't going back in"}},
{"s12_house_kid_drawing_049","any",2,"reg=family,rescue|tmp=fresh,seasoned|mood=sad|world=trees",{1,"There was kid drawings all up the hall - crayon, house, sun, dog, the usual",2,"That's sweet, in a way",1,"The last eight had the same tall fella in 'em - off to the side, in the trees, every time"}},
{"s12_house_nobody_lived_050","any",2,"reg=civilian,worker|tmp=seasoned|mood=grim|world=door,window,building",{1,"I once found a house with the realtor sign still in the yard. Had been empty for months",2,"Empty house must've looked like a good find",1,"Until I saw the worn path between the front window and the kitchen door. Somebody had been using it"}},
{"s12_mail_flag_down_001","any",2,"reg=family,civilian|tmp=fresh,seasoned|hour=19,23|mood=fear",{1,"I been putting a note in our mailbox every day for my brother - flag up, so he'd see it",2,"He ain't coming, honey",1,"I know that, the note's gone every morning and the flag's put back down"}},
{"s12_mail_emptied_daily_002","any",2,"reg=civilian,worker|tmp=seasoned|hour=20,2|mood=grim",{1,"Mail don't run, we all know the mail don't run",2,"Get to it",1,"Something empties that box out on Tanner Road, I put four rocks in it Monday to see, rocks are gone"}},
{"s12_mail_doll_shoe_003","any",2,"reg=civilian,family|tmp=fresh,seasoned|hour=21,3|mood=fear",{1,"I quit looking in mailboxes and I'll tell you exactly why",2,"Alright, tell me",1,"Four boxes in a row on Echo Creek Road had a little shoe in 'em - doll's shoe, same kind of shoe",2,"Same kind, or the same one?",1,"That's a hell of a question and I don't want it"}},
{"s12_mail_note_answered_004","any",3,"reg=civilian,worker|tmp=seasoned|hour=22,3|mood=fear",{1,"I left a note in the box at the Kelso place - just asking, just, is anybody out here",2,"And?",1,"Answered, different hand, but it answered",3,"What'd it say?",1,"'Not yet.' That's it, two words and not yet is the two words"}},
{"s12_mail_stamp_licked_005","any",2,"reg=worker,civilian|tmp=seasoned|mood=grim|world=road",{1,"There was a letter in that box, stamped, addressed, ready to go - dated the fourteenth",2,"So somebody wrote a letter last week",1,"Somebody wrote a letter last week and licked a stamp and walked out to the road to mail it"}},
{"s12_mail_our_names_006","any",2,"reg=family|tmp=fresh|hour=20,1|mood=fear",{1,"Somebody's been writing our names on the inside of our own mailbox lid",2,"Kids from the trailer park",1,"The baby's name is on there and we never told a soul out here the baby's name"}},
{"s12_mail_bills_stacked_007","any",2,"reg=civilian,worker|tmp=seasoned|mood=grim|world=road",{1,"Every box on that road is stuffed full and split open - except one",2,"One's empty",1,"One's emptied, every couple days - same box, nobody's living in that house, I been in it"}},
{"s12_mail_receipt_008","any",2,"reg=civilian,family|tmp=seasoned|hour=19,0|mood=fear",{1,"I found a store receipt in our box, handy Pantry, two dollars and change",2,"Old one blowed in",1,"Dated the twelfth, the Handy Pantry burnt on the ninth, Wanda - I watched it burn"}},
{"s12_mail_key_left_009","any",2,"reg=law|tmp=seasoned,veteran|mood=calm",{1,"Somebody's leaving house keys in the mailboxes on Halbert, tagged, too, little paper tags",2,"Tagged with the address?",1,"Tagged with how many's inside, that's the number on the tag, I checked two and I quit"}},
{"s12_mail_thank_you_010","any",2,"reg=civilian,worker|tmp=seasoned|hour=21,2|mood=grim",{1,"I left a can of beans in a box out past the bridge - sort of a, I don't know - sort of a gesture",2,"That's decent of you",1,"Next day there was a thank you note in there - proper one - Cursive",2,"Well, good",1,"It thanked me by name and I never signed nothing"}},
{"s12_mail_flag_up_all_011","any",2,"reg=civilian,family|tmp=fresh,seasoned|hour=6,10|mood=fear",{1,"Drove Tanner at daylight, every flag on every box was up - all of 'em",2,"Wind",1,"Wind don't put a flag up, you got to reach out and lift it"}},
{"s12_mail_letter_to_me_012","any",3,"reg=civilian,worker|tmp=seasoned|hour=22,4|mood=fear",{1,"There was an envelope in the box with my first name on it - not last name - first",2,"You open it?",1,"I did, blank paper, folded in three like a real letter",3,"Blank",1,"Folded in three, though, somebody took the trouble to fold it in three"}},
{"s12_mail_dead_drop_013","any",2,"reg=outlaw,crime,raider|tmp=predator,seasoned|mood=calm",{1,"We been using the box at the end of Frogtown for passing word - you know that",2,"Yeah, so?",1,"Somebody's reading it before us and putting it back the same way - same fold, same corner",2,"How'd you catch it?",1,"I put a hair in the fold - old trick, hair's gone and the note ain't moved a hair's width"}},
{"s12_mail_note_under_014","any",2,"reg=civilian,family|tmp=fresh|hour=20,2|mood=fear",{1,"I wrote 'we are at the church, please knock' and taped it up at the feed store",2,"That's a lot to give away",1,"Somebody wrote under it in pencil, 'we knocked.' We didn't hear a thing all week"}},
{"s12_mail_catalog_015","any",2,"reg=civilian,worker|tmp=seasoned|mood=sad",{1,"Seed catalog come in the Pruitt box after the fourth - nobody ever opened it",2,"Nobody's going to plant this year",1,"Somebody has, page corner's turned down on the sweet corn and it wasn't turned last time I looked"}},
{"s12_mail_address_wrong_016","any",2,"reg=worker,civilian|tmp=seasoned|mood=grim|world=road",{1,"House numbers on that whole stretch got changed - Repainted, all of 'em, neat as you like",2,"Changed to what?",1,"To numbers that ain't on that road - eight hundreds, road's a two hundred road"}},
{"s12_mail_box_moved_017","any",2,"reg=civilian,family|tmp=fresh,seasoned|hour=21,3|mood=fear",{1,"Our mailbox has moved about ten foot closer to the house since the fourth",2,"That ain't possible",1,"Post hole's fresh, there's three old holes behind it in a line, filled in"}},
{"s12_mail_soda_can_018","any",2,"reg=family,civilian|tmp=fresh|hour=19,1|mood=fear|world=summer",{1,"Somebody left a cold RC in our box, cold, in summer, with no ice in this county",2,"Did you drink it?",1,"Course I drank it, that's what's eating at me, I drank it before I thought about it"}},
{"s12_mail_list_of_us_019","any",3,"reg=civilian,worker,family|tmp=seasoned|hour=22,3|mood=fear|world=door",{1,"There's a list in the box at the end of our drive - six names on it",2,"Six of us here",1,"Six, I counted twice",3,"Anybody crossed off?",1,"Not yet, I'm going to go ahead and say not yet and then I'm going to go check the door"}},
{"s12_mail_dog_tag_020","any",2,"reg=civilian,worker|tmp=seasoned|mood=sad|world=building",{1,"Somebody put a dog collar in the Tandy mailbox, tag on it, phone number and all",2,"Whose dog?",1,"Tag says Roscoe, the Tandys never had a dog - I asked Glenda twice 'cause I didn't believe her"}},
{"s12_mail_same_day_021","any",2,"reg=civilian,family|tmp=seasoned|hour=20,1|mood=grim",{1,"Every note I've put out there comes back with the date changed to the ninth",2,"Changed by who?",1,"Changed, the ninth, every time, in my own handwriting - you go on and chew on that a minute"}},
{"s12_mail_asking_price_022","any",2,"reg=raider,gang|tmp=predator|mood=funny|world=road",{1,"We put word in the boxes down that road, half your gas or we come see you",2,"Anybody write back?",1,"One box wrote back, said we could have it all, come on up to the house, any night",2,"Well, good",1,"Ain't good, nobody says come on up to the house, we're going around that house"}},
{"s12_mail_flag_at_night_023","any",2,"reg=law,law|tmp=seasoned|hour=23,4|mood=calm",{1,"Sat on that box for three hours with the glasses on it - nothing came",2,"And the note?",1,"Gone at first light, I never took my eyes off it more than a minute to rub 'em"}},
{"s12_mail_to_the_dead_024","any",2,"reg=family,rescue|tmp=fresh,seasoned|mood=sad",{1,"I write to June and I put it in the box - I know how that sounds",2,"It don't sound like nothing to me",1,"The box is empty every morning, and I have decided I am not going to think about that too hard"}},
{"s12_mail_return_address_025","any",2,"reg=civilian,worker|tmp=seasoned|hour=21,2|mood=fear",{1,"There's a return address on the envelope in our box - that's what I keep chewing on",2,"Whose address?",1,"Ours, right address, right zip, spelled right, somebody's mailing us from our own house"}},
{"s12_mail_rural_route_026","any",2,"reg=worker|tmp=seasoned|mood=grim|world=water",{1,"I drove that route for nine years, I know which boxes stick and which ones you got to lift",2,"So?",1,"Somebody's been oiling the hinges, every box from the creek to the church swings clean now"}},
{"s12_mail_no_junk_027","any",2,"reg=civilian,family|tmp=seasoned|mood=grim",{1,"Every box on Bethel Ridge is picked clean, not tore up - clean",2,"Folks looking for checks",1,"Folks don't take the rubber bands, Earl, somebody took the rubber bands"}},
{"s12_mail_letters_sorted_028","any",2,"reg=law,rescue|tmp=seasoned|mood=grim|world=road",{1,"Front hall of the post office, somebody's been sorting - stacks by street, rubber banded",2,"Somebody's holding on to their job",1,"Then God bless 'em, but the stack for Halbert Street is the only one that keeps getting smaller"}},
{"s12_mail_answer_wrong_029","any",2,"reg=civilian,worker|tmp=seasoned|hour=22,4|mood=fear|world=building",{1,"Was anything took out of the box, is what I asked you",2,"There's a smell out there, like a cellar, right at the box, ten foot either way and it's gone",1,"That ain't what I asked",2,"I know it ain't"}},
{"s12_mail_trade_note_030","any",2,"reg=civilian,worker|tmp=seasoned|mood=calm",{1,"There's a trade going on through the boxes on Piney Fork - note in, goods out, nobody meets",2,"That's fine by me, I'd rather not meet nobody",1,"Me neither, till I asked for aspirin and got aspirin and a note asking after my chest pain"}},
{"s12_mail_flag_signal_031","any",3,"reg=military,elite|tmp=veteran|mood=calm|world=building",{1,"Mailbox flags along that route are being used as signals - up means something, down means something",2,"By who?",1,"Unknown - Pattern's consistent, up, up, down, up, for about four miles",3,"Want us to change one, see what happens?",1,"Negative, we're not the ones who find out what happens"}},
{"s12_mail_letters_burned_032","any",2,"reg=civilian,family|tmp=seasoned|hour=20,2|mood=grim",{1,"Little burn pile beside the box out at the Six place - just envelopes",2,"Somebody burning their bills, I'd do the same",1,"Every one of 'em burnt to the stamp and no further - you try burning an envelope to the stamp"}},
{"s12_mail_hedge_claim_033","any",2,"reg=civilian,worker|tmp=seasoned|hour=21,3|mood=fear",{1,"I ain't saying it was a man at that box - I'm saying it had boots on",2,"You saw boots",1,"I saw the grass laid over in the shape of boots and I saw it from a hundred yards and that's what I've got"}},
{"s12_mail_repeat_word_034","any",2,"reg=family,civilian|tmp=fresh|hour=22,4|mood=fear",{1,"And the lid was, the lid was already stood open when I got to it",2,"Slow down. What was there?",1,"It was standing open. And there was a nickel on the post, set up on its edge. Just a nickel"}},
{"s12_mail_you_know_place_035","any",2,"reg=civilian,worker|tmp=seasoned|mood=grim|world=door",{1,"You know the box shaped like a little barn? Out past the Yeager bins? Okay - so",2,"I know it",1,"The little doors on the barn get shut at night and opened in the morning - I been by four days running"}},
{"s12_mail_draft_witness_036","any",2,"reg=civilian,family|tmp=seasoned|hour=19,1|mood=fear|world=building,road",{1,"You'd have heard it too, anybody on that road would have heard it",2,"Heard what, exactly",1,"A mailbox lid, opening and shutting, twenty, thirty times, two in the morning, that's all it was"}},
{"s12_mail_flat_ending_037","any",2,"reg=worker,civilian|tmp=seasoned|mood=calm|world=vehicle",{1,"So I put the note in and I went back to the truck and I watched till it got light out",2,"Then?",1,"Then it got light out and the note was gone and I drove home - that's all that happened"}},
{"s12_mail_school_papers_038","any",2,"reg=family,rescue|tmp=seasoned|mood=sad",{1,"Somebody's putting school papers in the boxes - graded ones, spelling tests with stars on 'em",2,"From the school?",1,"From last spring, every kid's name on 'em is a name I know, and half of them ain't with us"}},
{"s12_mail_i_quit_039","any",3,"reg=civilian,worker,family|tmp=seasoned|hour=20,2|mood=grim",{1,"I'm done with the box, anybody wants to talk to me can come to the gate in daylight",2,"You said that last week",1,"I did, then somebody wrote 'in daylight then' and I ain't slept since",3,"Well, maybe it's somebody friendly",1,"Maybe it is, then they can come at noon and knock like a person"}},
{"s12_mail_receipts_of_us_040","any",2,"reg=law,swat|tmp=veteran|mood=calm|world=vehicle,building",{1,"Somebody's keeping a log of our patrol in a mailbox on our own route",2,"Times?",1,"Times, plate, how many in the car, neat little column - we're on there nine times",2,"We change the route",1,"We change the route and we don't tell nobody, not even dispatch - especially not dispatch"}},
{"s12_mail_letter_from_dad_041","any",2,"reg=family,civilian|tmp=fresh|hour=21,3|mood=sad",{1,"There was a letter from my daddy in the box - Postmarked the second",2,"That's before all this",1,"Two weeks it sat somewhere and got to me, he's asking me to come help him move a freezer"}},
{"s12_mail_i_shouldnt_042","any",2,"reg=civilian,family|tmp=seasoned|hour=23,4|mood=fear",{1,"It's late and I shouldn't get into this with you sitting watch",2,"I'm up either way",1,"The box at the bottom of the drive is full of hair - that's it, that's all I'm saying about it"}},
{"s12_mail_proof_object_043","any",2,"reg=civilian,worker|tmp=seasoned|mood=fear",{1,"I still got the paper - you want to see the paper? I'll go get it right now",2,"Just tell me what's on it",1,"Our watch times, four to eight, eight to twelve - somebody outside our fence wrote down our watch times"}},
{"s12_mail_gang_reply_044","any",2,"reg=gang,club|tmp=predator,seasoned|mood=grim",{1,"We left a name in that box - ours, figured folks ought to know who they're dealing with",2,"Bold",1,"Somebody wrote it back out, spelled right, and put a date beside it - two weeks out",2,"Meaning what?",1,"I don't know what it means and that is exactly the problem I've got"}},
{"s12_mail_postcard_045","any",2,"reg=civilian,family|tmp=seasoned|hour=19,23|mood=grim",{1,"Postcard in the box, picture of the courthouse, nothing wrote on the back",2,"Blank postcard",1,"Address is a house that burnt in June, and it's in our box, not theirs"}},
{"s12_mail_widow_walk_046","any",2,"reg=family,civilian|tmp=seasoned|hour=6,9|mood=sad",{1,"Lurlene still walks down to the box at eight every morning - rain or not",2,"There ain't any mail",1,"There's always something in it when she comes back up - she don't show me and I don't ask"}},
{"s12_mail_count_up_047","any",2,"reg=civilian,worker|tmp=seasoned|hour=20,2|mood=fear",{1,"One note in the box Monday - two Tuesday, three today, all different hands",2,"Folks out there wanting in",1,"All three say the same sentence, I'd take three strangers over that any day of the week"}},
{"s12_mail_dont_answer_048","any",3,"reg=civilian,family,worker|tmp=seasoned|hour=21,2|mood=grim|world=door,cold",{1,"New rule and I'm sorry about it, nobody answers anything left in that box",2,"What if it's somebody needing help?",1,"Then they can need it at the gate where I can see their face",3,"That's cold",1,"It's cold - write it on the door anyway so nobody has to argue with me about it"}},
{"s12_mail_flag_family_049","any",2,"reg=family|tmp=fresh|hour=20,1|mood=fear",{1,"Daddy, the flag was up and I didn't put it up",2,"Come inside, come on in the house",1,"I only asked you a question",2,"I know you did - come inside first and then I'll answer it"}},
{"s12_mail_corrects_detail_050","any",2,"reg=civilian,worker|tmp=seasoned|mood=grim|world=vehicle",{1,"It was a Ford at that box - Chevy, whatever it was, it was a truck and it had no plate",2,"Color?",1,"Dark, and the fella got out, opened the box, put something in, and got back in and sat there",2,"How long?",1,"Till I left, he was still sat there when I left"}},
{"s12_mon_baby_monitor_voice_001","any",2,"reg=family|tmp=fresh,seasoned|hour=22,4|mood=fear|world=inside",{1,"There's a man's voice on the baby monitor",2,"Go get her out of that room, go right now",1,"She's in here with me, she's been in here since supper, the monitor's in the empty room"}},
{"s12_mon_humming_002","any",2,"reg=family,civilian|tmp=fresh|hour=23,4|mood=fear|world=road",{1,"Somebody humming come through the monitor about two - low, like you'd do over a crib",2,"Them things pick up the neighbors, they always did",1,"The neighbors are the Kelsos and there ain't a Kelso left on that road - I checked their house myself"}},
{"s12_mon_counts_to_ten_003","any",3,"reg=family,civilian|tmp=fresh,seasoned|hour=0,5|mood=fear",{1,"It counts, on the monitor, one to ten, slow, then it starts over",2,"That's another monitor bleeding over, they're all on the same band",1,"That's what I told myself for two nights",3,"And now?",1,"Last night it counted to eleven, I want somebody else to hear it before I say any more"}},
{"s12_mon_unplugged_004","any",2,"reg=family|tmp=fresh,seasoned|hour=22,3|mood=fear|world=building",{1,"I unplugged the thing, pulled the cord out of the wall and set it on the dresser",2,"Good, that's the end of it then",1,"It's got a nine volt in it for when the power goes - I forgot about the nine volt"}},
{"s12_mon_says_her_name_005","any",2,"reg=family|tmp=fresh|hour=23,4|mood=fear",{1,"It said her name, not a word like her name - her name",2,"Which room's the unit in?",1,"Hers, and she's been sleeping in our bed since the tenth because I don't like that room"}},
{"s12_mon_answering_machine_006","any",2,"reg=civilian,family|tmp=seasoned|hour=20,2|mood=sad",{1,"Answering machine still had her on it - leave a message, we'll call you back",2,"You still got the tape?",1,"I ran the batteries flat playing it, now it's just the little red light"}},
{"s12_mon_new_message_007","any",3,"reg=civilian,worker|tmp=seasoned|hour=21,3|mood=fear",{1,"That machine in the house on Halbert says one new message",2,"Play it",1,"I did, thirty seconds of a room - chair scraping, somebody setting a glass down",3,"Wrong number, then, folks call and don't hang up",1,"Phones have been dead since the eighth, the machine says the message come in on the fifteenth"}},
{"s12_mon_cb_answers_008","any",2,"reg=civilian,worker|tmp=seasoned|hour=0,5|mood=fear",{1,"Called for a copy on nineteen about four this morning - got one",2,"That's good news, ain't it?",1,"He gave my handle back before I gave it, then he asked how the baby was doing"}},
{"s12_mon_scanner_our_road_009","any",2,"reg=law,civilian|tmp=seasoned|hour=22,4|mood=grim",{1,"Somebody's on the sheriff's channel reading out addresses, calm as Sunday",2,"Dispatch is nobody now, anybody can pick up a mic",1,"He read out this address forty minutes ago and then he said nine",2,"Nine what?",1,"There's six of us here - you asked, that's my answer, there's six of us here"}},
{"s12_mon_tape_in_machine_010","any",2,"reg=civilian,worker|tmp=seasoned|mood=fear|world=vehicle",{1,"There was a camcorder tape in a house out Echo Creek and a VCR still hooked to a car battery",2,"Somebody was watching something",1,"Twenty minutes of their own front door - nothing happens, then twenty minutes more of the same"}},
{"s12_mon_pager_011","any",2,"reg=civilian,worker|tmp=seasoned|hour=19,1|mood=grim",{1,"My pager's still going off, somebody out there wants me to call 'em back real bad",2,"Same number?",1,"Same number every time till Tuesday - Tuesday it started being my own number"}},
{"s12_mon_kid_talks_back_012","any",2,"reg=family|tmp=fresh|hour=21,2|mood=fear",{1,"The boy's been talking to somebody through the monitor, he holds the button down and talks",2,"There's no button on ours",1,"I know there ain't, he holds a spot on the side of it and he talks and he waits"}},
{"s12_mon_radio_pauses_013","any",2,"reg=civilian,worker|tmp=seasoned|hour=1,5|mood=fear",{1,"Whatever I say on that set, it comes back at me - my words, my voice, wrong timing",2,"Feedback off a repeater",1,"I said a thing I've never said out loud before just to test it - it come back"}},
{"s12_mon_learning_my_name_014","any",3,"reg=civilian,family|tmp=seasoned|hour=0,5|mood=fear",{1,"Voice on the monitor puts my name in every sentence - every single one",2,"Like what?",1,"'Sure, Wanda.' 'That's right, Wanda.' Like it's getting used to saying it",3,"Somebody's playing with you",1,"Then somebody's practicing, and I don't want to know what for"}},
{"s12_mon_channel_nineteen_reunion_015","any",2,"reg=civilian,family|tmp=seasoned|hour=20,2|mood=warm|world=vehicle",{1,"Her voice come over nineteen Tuesday and I had to sit down",2,"Where at?",1,"Right down on the floor of the truck, just sat there with the mic in my lap"}},
{"s12_mon_her_voice_wrong_016","any",2,"reg=civilian,family|tmp=seasoned|hour=22,4|mood=grim|world=building",{1,"I thought it was her on the radio, four nights I thought that",2,"And it wasn't",1,"It's her words, things she said to me in a kitchen in June, in order, in her voice, and she is in the ground"}},
{"s12_mon_military_net_017","any",3,"reg=military,elite|tmp=veteran|hour=0,5|mood=calm",{1,"Somebody's on our net using a dead callsign - Foxtrot one one",2,"Foxtrot's been off the board eleven days",1,"He has, whoever this is has the authentication table for the sixth",3,"Then we go to the alternate",1,"We go to the alternate and we don't say the reason on the air - pass it hand to hand"}},
{"s12_mon_static_breathing_018","any",2,"reg=civilian,worker|tmp=seasoned|hour=1,5|mood=fear|world=vehicle",{1,"There's somebody sitting on nine with the key down, no words, just the carrier",2,"Stuck mic in a wrecked car - happens",1,"It lets off when I talk and comes back on when I quit - six hours of that last night"}},
{"s12_mon_wrong_station_019","any",2,"reg=civilian,family|tmp=seasoned|hour=2,5|mood=grim",{1,"There's a station down the FM dial at two in the morning reading names",2,"Obituaries, the one out of Muldraugh does that at night",1,"These ain't dead folks, I heard three names off that list walk past my fence this week"}},
{"s12_mon_monitor_moves_020","any",2,"reg=family|tmp=fresh,seasoned|hour=21,3|mood=fear|world=building",{1,"I set the monitor on the kitchen table and went to bed with the other half",2,"And?",1,"About one it went quiet and about two you could hear it was outside - wind in it - crickets"}},
{"s12_mon_cassette_between_songs_021","any",2,"reg=civilian,family|tmp=seasoned|mood=sad|world=vehicle",{1,"She made me a tape for the truck, she talks between the songs, just a little",2,"That's something to have",1,"I only play the talking parts now, I'm going to wear the tape out on the talking parts and I know it"}},
{"s12_mon_phone_rings_022","any",2,"reg=civilian,worker|tmp=seasoned|hour=0,4|mood=fear|world=building",{1,"Kitchen phone rang last night - one ring - then nothing",2,"Line's cut at the pole, I cut it",1,"You cut it, I know you cut it, I'm telling you what the phone did anyway"}},
{"s12_mon_recorded_us_023","any",3,"reg=civilian,worker|tmp=seasoned|hour=20,2|mood=fear|world=road",{1,"There's a tape in that house with us on it",2,"Us how?",1,"Us talking at the fire - Sunday night, the part where Earl was cutting up about the beans",3,"That's a hundred yards from any road",1,"It's a hundred and forty, I stepped it off this morning, which is a stupid thing to have done"}},
{"s12_mon_dispatch_ghost_024","any",2,"reg=law|tmp=seasoned,veteran|hour=1,5|mood=calm",{1,"Somebody raised me as dispatch last night with the right call sign and the right cadence",2,"Give them a code you never use and see what comes back",1,"I did, he said stand by and then he read me my own unit history back - nine years of it"}},
{"s12_mon_walkman_025","any",2,"reg=civilian,family|tmp=fresh,seasoned|hour=22,3|mood=fear",{1,"Girl's got one of them little tape players with the headphones - batteries are dead",2,"Then it don't play",1,"She had it on her ears last night and she was nodding along - I took the batteries out in June"}},
{"s12_mon_monitor_two_rooms_026","any",2,"reg=family,civilian|tmp=seasoned|hour=23,4|mood=fear|world=building",{1,"We've got one monitor and one half, one of them's the talker and one's the listener",2,"Right",1,"So how am I hearing our own kitchen through the one in the bedroom - ours can't do that"}},
{"s12_mon_half_second_late_027","any",2,"reg=civilian,worker|tmp=seasoned|hour=19,1|mood=fear",{1,"That fella on the radio answers about a half second late - every time",2,"Bad signal",1,"Every time, exact same delay, like there's somebody in between telling him what to say"}},
{"s12_mon_broadcast_repeats_028","any",2,"reg=civilian,rescue|tmp=seasoned|hour=5,9|mood=grim",{1,"The emergency thing on the AM dial's been playing the same forty seconds since the ninth",2,"Tape on a loop, somebody set it and left",1,"Yesterday it skipped, you could hear a room behind it for about two seconds - then it got fixed"}},
{"s12_mon_child_sings_back_029","any",2,"reg=family|tmp=fresh|hour=21,2|mood=grim",{1,"I ain't going to say I heard a child on that monitor - I'm going to say I heard a high voice",2,"Same thing, honey",1,"It ain't, and I'd take it kindly if you'd let me keep the difference for one more night"}},
{"s12_mon_tape_labeled_030","any",2,"reg=civilian,worker|tmp=seasoned|mood=fear|world=building",{1,"Shoebox of tapes in that back bedroom, all labeled in pencil - dates and times",2,"How far back?",1,"April, four a night, every night, straight through to the sixteenth of this month"}},
{"s12_mon_hedge_number_031","any",2,"reg=civilian,family|tmp=seasoned|hour=22,4|mood=fear",{1,"Four times it's come through - five, I'd say five, counting the night I was half asleep",2,"Same voice?",1,"Same voice, man, older, real polite, that's what I can't get past, how polite it is"}},
{"s12_mon_apologizes_032","any",2,"reg=family,civilian|tmp=fresh|hour=1,5|mood=fear",{1,"I'm sorry, I know you're on watch at four, I couldn't sit in that room by myself anymore",2,"Come sit, I'm awake",1,"It said goodnight, on the monitor - it said goodnight and then it shut off"}},
{"s12_mon_refuse_last_bit_033","any",3,"reg=civilian,family|tmp=seasoned|hour=22,3|mood=fear|world=building",{1,"So I carried it out to the porch to see if it'd clear up out there",2,"Did it?",1,"It got louder on the porch, then it said one more thing and I come inside",3,"What'd it say?",1,"I ain't telling that part - Junior was on the porch with me - ask Junior"}},
{"s12_mon_flat_close_034","any",2,"reg=civilian,worker|tmp=seasoned|hour=5,9|mood=calm",{1,"So we sat up with it till daylight and it quit about five",2,"Then what",1,"Then nothing, we had breakfast - that's all that happened"}},
{"s12_mon_burned_it_035","any",2,"reg=family,civilian|tmp=seasoned|hour=19,23|mood=grim",{1,"I put that monitor in the burn barrel, both halves, battery and all",2,"Feel better?",1,"I did for about a day, then the boy asked me who's going to listen for her now"}},
{"s12_mon_swear_to_it_036","any",2,"reg=civilian,family|tmp=fresh,seasoned|hour=21,3|mood=fear",{1,"I'll put my hand on a Bible on this one - go on and get it, I'll do it tonight",2,"Nobody's doubting you",1,"You are, a little, and I don't blame you, I'd doubt me too, but I heard what I heard"}},
{"s12_mon_friend_of_friend_037","any",2,"reg=civilian,worker|tmp=seasoned|hour=20,2|mood=fear",{1,"This ain't my story, woman that trades eggs at the bridge told me and she don't tell stories",2,"Go on",1,"Said her monitor picked up a woman singing to a baby - said she knew the voice and she buried the voice"}},
{"s12_mon_coda_rule_038","any",2,"reg=family,civilian|tmp=seasoned|hour=20,5|mood=grim|world=building",{1,"Midnight, the radios go off. Every one in this house",2,"What if somebody calls for us?",1,"They can call at eight in the morning. I'm not leaving them on past midnight"}},
}
